using System.Windows; using AutoPecasERP.Core.Entities; using AutoPecasERP.Data.Context; using AutoPecasERP.Services.Compras; using Microsoft.EntityFrameworkCore;
namespace AutoPecasERP.Desktop.Views; public partial class ComprasWindow:Window { public ComprasWindow(){InitializeComponent();Loaded+=async(_,__)=>await Carregar();} async Task Carregar(){using var db=new ErpDbContext();var q=db.PedidosCompra.Include(x=>x.Fornecedor).AsQueryable();if(!string.IsNullOrWhiteSpace(Busca.Text))q=q.Where(x=>x.Numero.Contains(Busca.Text)||(x.Fornecedor!=null&&x.Fornecedor.Empresa.Contains(Busca.Text)));GridPedidos.ItemsSource=await q.OrderByDescending(x=>x.Data).ToListAsync();} async void Pesquisar_Click(object s,RoutedEventArgs e)=>await Carregar(); async void Novo_Click(object s,RoutedEventArgs e){var w=new PedidoCompraEditWindow{Owner=this};if(w.ShowDialog()==true)await Carregar();} async void Receber_Click(object s,RoutedEventArgs e){if(GridPedidos.SelectedItem is not PedidoCompra p)return;if(MessageBox.Show($"Confirmar recebimento do pedido {p.Numero}?","Recebimento",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;try{using var db=new ErpDbContext();await new CompraService(db).ReceberAsync(p.Id);await Carregar();MessageBox.Show("Recebimento concluído. Estoque e financeiro atualizados.");}catch(Exception ex){MessageBox.Show(ex.Message);}} }